import urllib.request
import re

url = 'https://octowow.st/db/?itemsets'
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:158.0) Gecko/20100101 Firefox/158.0',
    'Cookie': 'phpbb3_3p6u9_u=1; phpbb3_3p6u9_k=; phpbb3_3p6u9_sid=454afb9a430c7fd3d54e75be0cfc3231; __bf_clearance_v2=e4fa044b4c4c34f06e2f60f378cbb39ede547be7310dadcb1b7e3766fd703ac4; XSRF-%3D; octowow_%3D',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
}
req = urllib.request.Request(url, headers=headers)
with urllib.request.urlopen(req, timeout=10) as resp:
    html = resp.read().decode('utf-8', errors='ignore')

print('Status:', resp.status, 'Length:', len(html))
m = re.findall(r'\[(\d+)\]\s*=\s*\{[^\}]*name:[^\}]*\}', html)
print('Found itemset definitions:', len(m))
for s in m:
    if any(k in s.lower() for k in ['law', 'judg', 'redemp', 'might', 'wrath', 'dread']):
        print(s)
